class Animation {
  duration: number;
  keyframes: Keyframe[];
  currentKeyframeIndex: number;
  currentTime: number;
  easingFunction: (t: number) => number;

  constructor() {
    this.duration = 0;
    this.keyframes = [];
    this.currentKeyframeIndex = 0;
    this.currentTime = 0;
  }

  addKeyframe(property: string, value: any, time: number): void {
    this.keyframes.push({ property, value, time });
  }

  update(deltaTime: number): void {
    this.currentTime += deltaTime;
    this.interpolate();
  }

  interpolate(): void {
    if (!this.keyframes.length || this.isDone()) return;

    const nextKeyframeIndex = this.findNextKeyframeIndex();
    const percentComplete = (this.currentTime - this.keyframes[this.currentKeyframeIndex].time) / (nextKeyframeIndex.time - this.keyframes[this.currentKeyframeIndex].time);

