function switchAdjectiveOrder(sentence) {
  // Define a list of common English adjectives for recognition
  const adjectives = ["beautiful", "green", "red", "blue", "big", "little", "old", "new", "happy", "sad", "long", "short", "thin", "fat"];

  // Create a regex pattern to match adjectives before a noun
  const adjRegex = /(([a-z]+[^\s]*[a-z]\s*){2,}[a-z]+[\s]+([a-z][^\.?!]*[.\?!]|[a-z]+(?:[a-z][^\.?!]*[.\?!]|$))/g;

  let match;
  let newSentence = sentence;

  // Use a loop to find all matches of adjective sequences in the sentence
  while ((match = adjRegex.exec(sentence)) !== null) {
    // Extract the matched adjective sequence as an array
    const adjectivesArray = match[1].split(" ");

    // Reverse the order of adjectives in the array
    const reversedAdjectives = [...adjectivesArray].reverse();

    // Join the reversed adjectives back into a single word or phrase
    const reversedAdjectiveString = reversedAdjectives.join(" ");

    // Replace the original adjective sequence in the sentence with the reversed one
    newSentence = newSentence.replace(match[0], reversedAdjectiveString);
  }

  return newSentence;
}

