const int numPixels = 60;
const int pixelPin = 0; // replace with your pixel data pin number

Adafruit_NeoPixel pixels(numPixels, pixelPin, NEO_GRB + NEO_KHZ800);
Debounce debouncer(buttonPin, DEBOUNCE_50MS);
