// {
//   "address": "1A1zP1eP5QGefi2DMPTfTL5SLmv7DivfNa", // The generated wallet's address.
//   "memo": "Optional memo string.", // An optional memo for transactions using this wallet.
//   "network": "BTC", // The selected network, i.e., "BTC" for Bitcoin mainnet or "BCTest" for Bitcoin testnet.
