 ```vbnetapi
/**
 * @class WalletApi
 * @description This API provides endpoints for generating new wallets and retrieving associated information.
 */

class WalletApi {
  /**
   * @method createWallet
   * @param {string} token - User access token to authenticate the request.
   * @param {string} coin - The desired cryptocurrency for the new wallet (e.g., BTC, ETH, etc.).
   * @param {string} network - The blockchain network for the new wallet (e.g., mainnet, testnet, etc.).
   * @returns {Object} A JSON object containing the following properties:
   *      - address: The newly generated wallet address.
   *      - memo: A memo or note associated with the wallet.
   *      - network: The specified network for the wallet.
   *      - coin: The specified coin for the wallet.
   */
  static async createWallet(token, coin, network) {
    const url = '/account/wallet';
    const params = { token, coin, network };
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(params)
    });

    if (!response.ok) {
      throw new Error('Error creating wallet');
    }

    return response.json();
  }
}
```
Example usage:

```javascript
const userToken = 'abc123';
const coin = 'BTC';
const network = 'mainnet';

try {
  const result = await WalletApi.createWallet(userToken, coin, network);
  console.log(result);
} catch (error) {
  console.error(error);
}
```

