using System.Threading.Tasks;

public class RestServiceWrapper<T>
{
    private readonly string _baseUrl;
    private readonly HttpClient _httpClient;
    private string _authToken;

    public RestServiceWrapper(string baseUrl)
    {
        _baseUrl = baseUrl;
        _httpClient = new HttpClient();
    }

    public async Task<T> GetAsync(string endpoint)
    {
        await AddAuthTokenToRequestHeader();

        HttpResponseMessage response = await _httpClient.GetAsync($"{_baseUrl}/{endpoint}");
        response.EnsureSuccessStatusCode();

        string responseBody = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<T>(responseBody);
    }

    public async Task<T> PostAsync(string endpoint, T data)
    {
        string jsonData = JsonConvert.SerializeObject(data);
        StringContent content = new StringContent(jsonData, Encoding.UTF8, "application/json");

        await AddAuthTokenToRequestHeader();

        HttpResponseMessage response = await _httpClient.PostAsync($"{_baseUrl}/{endpoint}", content);
        response.EnsureSuccessStatusCode();

        string responseBody = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<T>(responseBody);
    }

    public void SetAuthToken(string authToken)
    {
        _authToken = authToken;
    }

    private async Task AddAuthTokenToRequestHeader()
    {
        if (!string.IsNullOrEmpty(_authToken))
        {
            _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _authToken);
        }
    }
}
