function determineProtocol(inputData) {
  let protocol;
  if (inputData.protocol) { // Check if protocol is already provided in inputData
    protocol = inputData.protocol;
  } else {
    if (inputData.sourceIP && inputData.destinationIP) { // If source and destination IPs are present
      if (inputData.port === 80) { // If port number is 80
        protocol = "HTTP";
