function determineProtocol(inputData) {
  let ipVersion; // Assumes input IPs are in valid IPv6 format
  try {
    ipVersion = new IPv6Address(inputData.sourceIP).version();
  } catch (error) {
    // If IP address is not valid IPv6, assume IPv4 or other and default to HTTP
    ipVersion = 4;
  }

  if (ipVersion === 6 && inputData.port === 80) {
    return "HTTP over IPv6 (Option B)";
  }

