import { useState } from 'react';

const useTemperatureConverter = (initialValue) => {
  const [temperature, setTemperature] = useState(initialValue);
  const [unit, setUnit] = useState('celsius');

  const convertToFahrenheit = () => {
    setUnit('fahrenheit');
