 To retrieve the username from a JWT (JSON Web Token) in an ASP.NET C# WebApi, you can use the `ClaimsPrincipal` and `ClaimsIdentity` classes provided by the `System.Security.Claims` namespace. Here's how you can achieve this:

1. First, ensure that your WebApi project is configured to use JWT for authentication. Typically, this would involve using a middleware or a library like `Microsoft.AspNetCore.Authentication.JwtBearer`. Make sure to configure it properly in the `ConfigureServices` method in the `Startup.cs` file.

2. In your controller action or method where you want to access the username, you can get the current user information by injecting the `IHttpContextAccessor` into your constructor.

Here's an example of how you can implement this:

```csharp
using System;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.DependencyInjection;
using System.Security.Claims;
using System.Threading.Tasks;

[Route("api/[controller]")]
[ApiController]
public class ValuesController : ControllerBase
{
    private readonly ILogger<ValuesController> _logger;
    private readonly IHttpContextAccessor _httpContextAccessor;

    public ValuesController(ILogger<ValuesController> logger, IHttpContextAccessor httpContextAccessor)
    {
        _logger = logger;
        _httpContextAccessor = httpContextAccessor;
    }

    // Your API actions go here...

    [HttpGet("username")]
    public async Task<ActionResult<string>> GetUsername()
    {
        if (!User.Identity.IsAuthenticated)
            return BadRequest("You need to be authenticated to access this resource.");

        ClaimsIdentity claimsIdentity = (ClaimsIdentity)User.Identity;
        ClaimsPrincipal claimsPrincipal = new ClaimsPrincipal(claimsIdentity);
        string username = claimsPrincipal.FindFirst(x => x.Type == ClaimTypes.Name).Value;

        return Ok(username);
    }
}
```

