    @Override
    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
        OAuth2User oAuth2User = oauth2UserService.loadUserByClientIdAndUserId(clientId, username);
        return new org.springframework.security.core.userdetails.User(oAuth2User.getUsername(), oAuth2User.getPassword(), getAuthorities(oAuth2User));
    }

    private Collection<? extends GrantedAuthority> getAuthorities(OAuth2User oAuth2User) {
        List<GrantedAuthority> authorities = new ArrayList<>();
        // Add authorities based on the OAuth user info
        return authorities;
    }
}
```

