$min_purchases = 3;

// Query to get the list of customers who have purchased the specified product at least three times in a week
$sql = "SELECT customer_id, COUNT(*) as num_purchases FROM coffee_transactions WHERE product_name = '$product' AND purchase_date >= DATE_SUB(NOW(), INTERVAL 1 WEEK) GROUP BY customer_id HAVING num_purchases >= $min_purchases";

// Execute the query
$result = $conn->query($sql);

// Store the results in an array
$loyal_customers = [];

// Fetch the results and add them to the array
if ($result->num_rows > 0) {
    while($row = $result->fetch_assoc()) {
        $loyal_customers[] = $row['customer_id'];
    }
} else {
    echo "No loyal customers found.";
}

// Close the connection
$conn->close();
?>
```

