# Helper function to check if a single element can be converted to numeric
is_numeric <- function(x) {
  tryCatch(as.numeric(x), error = function(e) NA, silent = TRUE) != NA
}

# Function to check if all non-NA elements in a character vector can be converted to numeric
check_numeric <- function(char_vector) {
  # Filter out NA elements and apply is_numeric function to the remaining elements
  numeric_elements <- sapply(!is.na(char_vector) & is_numeric(char_vector), FUN = identity)

  # Check if the length of the filtered vector matches the original one
  if (length(numeric_elements) == length(char_vector)) {
    return(TRUE)
  } else {
    return(FALSE)
  }
}

