 Here's an example of a simple decorator for a Nest.js middleware function that checks the `NODE_ENV` environment variable and calls the next handler if it's set to `true`, otherwise returns `false`. This decorator increases both helpfulness and verbosity.

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { NestMiddleware } from 'nest';
import { Response, Request, NextFunction } from 'express';

@NestMiddleware()
export class NodeEnvCheckMiddleware implements NestMiddleware {
  use(req: Request, res: Response, next: NextFunction) {
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'true') {
      next();
    } else {
      res.status(403).json({ message: 'Access denied. NODE_ENV must be set to "true".' });
    }
  }
}

// Create a decorator to apply this middleware to specific routes or controllers
export const NodeEnvCheck = createParamDecorator(
  (data: unknown, ctx: ExecutionContext): boolean => {
    const request = ctx.switchToHttp().getRequest();
    const middleware = reflect.getMetadata('middleware', ctx.getHandler());

    if (!middleware || !middleware.find((m) => m.constructor.name === 'NodeEnvCheckMiddleware')) {
      throw new Error('NodeEnvCheck decorator must be used with NodeEnvCheckMiddleware');
    }

    return true;
  },
);
```

Usage:

```typescript
