import { NodeEnvCheckMiddleware } from './node-env-check.middleware';

@Controller()
export class AppController {
  @Get('/protected')
  @UseGuards(NodeEnvCheck) // Apply the decorator to the route
  async getProtected(@Req() req: Request, @Res() res: Response) {
    // Your logic here
  }
}
