import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"isn't", "am not", "doesn't", "does not", "aren't", "are not", "haven't", "have not", "won't", "will not", "can't", "can not", "couldn't", "could not", "shouldn't", "should not", "wouldn't", "would not"}
