			doubleNegativeFound = true
			break
		}
		prevToken = token
	}

	if doubleNegativeFound {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func containsNegation(word string) bool {
	for _, negation := range negativeWords {
		if strings.Contains(strings.ToLower(word), negation) {
			return true
		}
	}
	return false
}
```

